package com.bank.securegrpc.interceptor;

import io.grpc.*;
import net.devh.boot.grpc.server.interceptor.GrpcGlobalServerInterceptor;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

// Server interceptor: validate the JWT in call metadata; reject unauthenticated calls.
@GrpcGlobalServerInterceptor
public class JwtServerInterceptor implements ServerInterceptor {
    private static final Logger log = LoggerFactory.getLogger(JwtServerInterceptor.class);
    private static final Metadata.Key<String> AUTH_KEY =
        Metadata.Key.of("Authorization", Metadata.ASCII_STRING_MARSHALLER);
    public static final Context.Key<String> USER_CTX = Context.key("user");

    @Override
    public <ReqT, RespT> ServerCall.Listener<ReqT> interceptCall(
            ServerCall<ReqT, RespT> call, Metadata headers, ServerCallHandler<ReqT, RespT> next) {
        String auth = headers.get(AUTH_KEY);
        if (auth == null || !auth.startsWith("Bearer ")) {
            log.warn("gRPC call rejected: missing bearer token");
            call.close(Status.UNAUTHENTICATED.withDescription("missing token"), new Metadata());
            return new ServerCall.Listener<>() { };
        }
        String token = auth.substring(7);
        String subject = validate(token);     // verify signature + expiry
        if (subject == null) {
            call.close(Status.UNAUTHENTICATED.withDescription("invalid token"), new Metadata());
            return new ServerCall.Listener<>() { };
        }
        log.info("gRPC call authenticated for subject {}", subject);
        // attach subject to gRPC Context so the service knows who called
        Context ctx = Context.current().withValue(USER_CTX, subject);
        return Contexts.interceptCall(ctx, call, headers, next);
    }

    private String validate(String token) {       // replace with real JWT library verify
        return token.startsWith("valid-") ? token.substring(6) : null;
    }
}
