package com.bank.securegrpc.service;

import com.bank.securegrpc.gen.*;
import com.bank.securegrpc.interceptor.JwtServerInterceptor;
import io.grpc.stub.StreamObserver;
import net.devh.boot.grpc.server.service.GrpcService;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import java.math.BigDecimal;
import java.util.UUID;

@GrpcService      // registers with grpc-spring-boot-starter, extends generated ImplBase
public class TransferGrpcService extends TransferServiceGrpc.TransferServiceImplBase {
    private static final Logger log = LoggerFactory.getLogger(TransferGrpcService.class);

    @Override
    public void transfer(TransferRequest req, StreamObserver<TransferResponse> obs) {
        String user = JwtServerInterceptor.USER_CTX.get();   // set by the interceptor
        BigDecimal amount = new BigDecimal(req.getAmount());
        log.info("Authenticated user {} transfers Rs.{} {}->{}",
            user, amount, req.getFromAccount(), req.getToAccount());
        obs.onNext(TransferResponse.newBuilder()
            .setTransferId("TXF-" + UUID.randomUUID())
            .setStatus("COMPLETED").build());
        obs.onCompleted();
    }
}
