package com.bank.securegrpc.client;

import com.bank.securegrpc.gen.*;
import io.grpc.Metadata;
import io.grpc.stub.MetadataUtils;
import net.devh.boot.grpc.client.inject.GrpcClient;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Component;
import java.util.concurrent.TimeUnit;

@Component
public class TransferGrpcClient {
    private static final Logger log = LoggerFactory.getLogger(TransferGrpcClient.class);

    // @GrpcClient injects a stub wired with mTLS + keep-alive from application.yml.
    @GrpcClient("account-service")
    private TransferServiceGrpc.TransferServiceBlockingStub stub;

    public String transfer(String from, String to, String amount, String jwt) {
        Metadata md = new Metadata();
        md.put(Metadata.Key.of("Authorization", Metadata.ASCII_STRING_MARSHALLER),
               "Bearer " + jwt);
        TransferResponse resp = stub
            .withInterceptors(MetadataUtils.newAttachHeadersInterceptor(md))
            .withDeadlineAfter(2, TimeUnit.SECONDS)   // per-call deadline (propagates)
            .withCompression("gzip")                  // gzip the request payload
            .transfer(TransferRequest.newBuilder()
                .setFromAccount(from).setToAccount(to).setAmount(amount).build());
        log.info("Transfer {} status={}", resp.getTransferId(), resp.getStatus());
        return resp.getStatus();
    }
}
